<!--vbase-->
<template>
  <q-markup-table class="full-width" v-if="!tableData || tableData.length == 0">
    <thead>
      <tr class="back-white">
        <th>{{ $t('no_data_found') }}</th>
      </tr>
    </thead>
  </q-markup-table>
  <q-table
    v-else
    :rows="tableRows"
    :columns="tableColumns"
    hide-bottom
    :rows-per-page-options="[0]"
    style="overflow: auto; height: auto; max-height: 500px"
    class="text-uppercase sticky-header transparent-header"
  />
</template>

<script lang="ts">
import { defineComponent, ref } from 'vue';

export default defineComponent({
  el: '#app',
  mixins: [],
  props: {
    tableData: {
      type: {} as any,
      default: [],
    },
  },
  components: {},
  data() {
    return {
      tableColumns: ref([] as any),
      tableRows: ref([] as any),
    };
  },
  mounted: function () {
    this.prepareTableData();
  },

  methods: {
    prepareTableData() {
      if (!this.tableData || this.tableData.length == 0) {
        return;
      }
      this.prepareTableColumns();
      this.prepareTableRows();
    },
    prepareTableColumns() {
      const row = this.tableData[0];
      for (let columnName of Object.keys(row)) {
        if (columnName.startsWith('_')) {
          continue;
        }
        this.tableColumns.push({
          name: columnName,
          label: this.$t(columnName),
          field: columnName,
          align: 'left',
          sortable: false,
        });
      }
    },
    prepareTableRows() {
      for (let row of this.tableData) {
        this.tableRows.push(row);
      }
    },
  },
  setup() {
    return {};
  },
});
</script>

<style lang="scss" scoped></style>
