<template>
  <div class="row">
    <div class="col-sm-12 col-md-5 col-lg-5">
      <BackToSettings
        :back_to_rotue="'/ready_for_approval_v3/' + docId"
        :label="'back'"
      />
    </div>
    <div class="col-sm-12 col-md-7 col-lg-7">
      <div class="col-auto q-pt-sm">
        <q-btn
          outline
          color="primary"
          :label="viewExportJson ? $t('view_summery') : $t('view_export_json')"
          class="q-mr-lg float-right"
          @click="viewExportJson = !viewExportJson"
        />
      </div>
    </div>
  </div>

  <div class="row highlighted-back q-pl-md q-pr-md q-pb-md" v-if="error">
    <ErrorDocumentView />
  </div>
  <div class="row approval-conatiner" v-else>
    <div class="q-pl-md full-width">
      <q-splitter
        v-model="splitterModel"
        @update:model-value="windowResize()"
        class="approval-content-area"
      >
        <template v-slot:before>
          <!-- Document Image Panel -->
          <div class="back-white q-pa-sm" style="border-radius: 5px">
            <div class="full-width" v-if="viewExportJson">
              <JsonViewer :jsonData="exportJson" />
            </div>
            <div class="full-width white-inputs full-height" v-else>
              <div
                class="row"
                v-if="layoutSettings && Object.keys(layoutSettings).length > 0"
              >
                <div
                  class="col-sm-12 col-md-12 col-lg-12 secondary-c-text text-h6 q-pt-sm q-pb-sm text-weight-bold"
                >
                  {{ $t('summary') }}
                </div>
                <template v-for="field in summeryLayout" :key="field['name']">
                  <div
                    class="col-sm-6 col-md-6 col-lg-6 q-pa-sm input-text-28px"
                  >
                    {{
                      getLabelForFormBuilder(
                        layoutSettings[field.name],
                        '',
                      )
                    }}
                    <q-input
                      outlined
                      :disable="true"
                      dense
                      v-model="field.formatted_value"
                    />
                  </div>
                </template>
              </div>
              <q-separator class="q-mt-lg q-mb-sm" />

              <div class="full-width">
                <q-tabs
                  v-model="tableTabs"
                  class="text-weight-bold align-tabs-left"
                >
                  <q-tab
                    draggable="false"
                    class="text-left po-tab"
                    v-for="(rows, index) in tablesLayout as any"
                    :key="index"
                    :name="index as any"
                    :data-name="index"
                    :label="$t(index as any)"
                    tabindex="0"
                  />
                </q-tabs>
                <q-separator />

                <q-tab-panels v-model="tableTabs" animated>
                  <q-tab-panel
                    v-for="(table, index) in tablesLayout as any"
                    :key="index"
                    :name="index"
                  >
                    <GenericReadOnlyTable :tableData="table" />
                  </q-tab-panel>
                </q-tab-panels>
              </div>
            </div>
          </div>
        </template>

        <template v-slot:after>
          <!-- Document Fields Panel -->
          <div class="full-width q-pl-sm q-pr-sm">
            <div class="invisible absolute position-absolute">
              <div class="row">
                <div class="q-mr-auto">
                  <q-icon
                    class="up-arrow cursor-pointer"
                    @click="prevImage"
                    name="expand_less"
                    size="sm"
                  >
                    <q-tooltip>{{ $t('previous') }}</q-tooltip>
                  </q-icon>

                  <q-icon
                    class="down-arrow cursor-pointer"
                    @click="nextImage"
                    name="expand_more"
                    size="sm"
                  >
                    <q-tooltip>{{ $t('next') }}</q-tooltip>
                  </q-icon>

                  <span class="page-numbers"
                    >{{ currentPage() }}/{{ images.length }}
                    {{ $t('page_number_text') }}</span
                  >
                </div>
                <div class="panel-middle mobile-hide">
                  {{ $t('summary') }}
                </div>
                <div class="panel-right mobile-hide">
                  <span
                    class="cursor-pointer q-mr-md text-uppercase"
                    @click="downloadFile"
                    >{{ $t('download') }}</span
                  >
                  <span class="doc-name">{{ record.filename }}</span>
                </div>
              </div>
            </div>
            <div class="full-width" :key="refreshAnnotationView">
              <div
                class="full-width full-height"
                id="image_container"
                style="position: relative"
              >
                <AnnotationView
                  ref="child_comp"
                  :enableEditing="enable_editing"
                  :cropUrl="image + '?' + tokenQueryParam"
                  :width="imageWidth"
                  :screenmode="screenmode"
                  :selectFont="selectFont"
                  :selectFontSize="selectFontSize"
                  :selectColor="selectColor"
                />
              </div>
            </div>
          </div>
        </template>
      </q-splitter>
    </div>
  </div>

  <Loader />
  <q-footer class="validation-status-bar back-white">
    <q-toolbar class="row justify-start">
      <span class="footer-filename">{{ record.filename }}</span>
      <q-btn size="md" flat dense class="q-ml-xs" @click="downloadFile">
        <q-icon name="download" style="color: #8a8a8a" />
      </q-btn>
      <q-separator vertical class="q-mx-md" />
      <span class="footer-status-message">
        {{ $t('summary') }}
      </span>
      <q-separator vertical class="q-mx-md" />
      <span class="cursor-pointer">
        {{ pending_approval_doc_count }} {{ $t('invoices_for_release') }}
      </span>
      <q-separator vertical class="q-mx-md" />

      <q-space />

      <q-separator vertical class="q-mx-xs" />
      <q-btn
        :disable="page == 1"
        icon="keyboard_arrow_up"
        flat
        class="validation-view-page-button icon-grey"
        @click="prevImage"
      />
      <span class="footer-status-message q-px-sm"
        >{{ currentPage() }}/{{ images.length }}</span
      >
      <q-btn
        :disable="page == images.length"
        icon="keyboard_arrow_down"
        flat
        class="validation-view-page-button icon-grey"
        @click="nextImage"
      />
    </q-toolbar>
  </q-footer>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { useImageAuth } from 'src/composables/useImageAuth';
import axios from 'axios';
import { useQuasar } from 'quasar';
import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';
import { DOC2API_URL } from 'src/pages/APIs';
import { downloadDocumentFile } from 'src/utils/download';
import helperUtil from 'src/utils/helperUtil';
import type { dynamicObj } from 'src/pages/assets';
import Loader from 'src/components/Loader.vue';
import helperMixin from 'src/mixins/helperMixin.js';
import { readOnlyDocStatus } from 'src/constants';
import JsonViewer from 'src/components/JsonViewer.vue';
import { api, getAuthorizationToken } from 'pages/APIs';
import { documentDetailApiService } from 'src/services';
import displayFieldLabel from 'src/utils/displayFieldLabel';
import ErrorDocumentView from 'src/pages/Errors/ErrorDocumentView.vue';
import { cleanUpImagesUrl, cleanUpImagePath } from 'src/utils/viewImages';
import { addOrgIdQueryString } from 'src/utils/organization/org_id_helper';
import GenericReadOnlyTable from 'src/components/GenericReadOnlyTable.vue';
import BackToSettings from 'src/pages/Settings/Components/BackToSettings.vue';
import { default_stamp } from 'src/pages/ValidationScreen/components/Annotation/helper.js';
import AnnotationView from 'src/pages/ValidationScreen/components/Annotation/annotationView.vue';
import {
  useDocumentStore,
  useDashboardStore,
  useDocAttributesStore} from 'src/store/main';
import { ApiExceptions } from 'src/exceptions/index';
const $ = document.querySelector.bind(document);

export default defineComponent({
  el: '#app',
  mixins: [helperMixin, helperUtil, displayFieldLabel],
  components: {
    Loader,
    JsonViewer,
    AnnotationView,
    BackToSettings,
    ErrorDocumentView,
    GenericReadOnlyTable,
  },
  data() {
    return {
      tableTabs: ref<any>(''),
      summeryLayout: ref<any>({} as dynamicObj),
      tablesLayout: ref<any>({} as dynamicObj),
      layout: ref<any>({} as dynamicObj),
      docId: '',
      default_stamp,
      imageWidth: 0,
      imageHeight: 0,
      splitterModel: ref<any>(50),
      enable_editing: ref<any>(false),
      viewExportJson: ref<any>(false),
      refreshAnnotationView: ref<any>(0),
      exportJson: ref<any>([] as any),
      layoutSettings: ref<any>({} as any),
    };
  },
  beforeRouteLeave: function (to: any, from: any, next: any) {
    // Before leaving this page, lets first reset everything
    this.restoreBeforeLeave();
    next();
  },
  mounted: async function () {
    let doc_id = this.$route.params.id as string;

    this.selectedStamp = this.default_stamp;
    this.getDocAnnotations(doc_id);
    await this.fetchAttributes(this.record.doc_type);

    window.addEventListener('resize', this.windowResize);
    document.body.addEventListener('click', this.mouseClicked, true);

    (<any>window).suc = this;
    this.init();

    for (let x = 1; x <= 80; x++) {
      this.fontSizes.push(x.toString() + 'pt');
    }
  },
  unmounted: function () {
    window.removeEventListener('resize', this.windowResize);
  },
  methods: {
    async init() {
      if (!this.$route.params.id) {
        this.$router.push('/dashboard');
      }

      this.docId = this.$route.params.id as string;
      await this.getInvoiceDataByDocId(this.docId);
      this.getUpdatedFieldSettings();

      this.renderPendingRecordsCountView();
      this.renderNextPrevLinkBtns();

      await this.getSummeryData();
      if (readOnlyDocStatus.includes(this.record.status)) {
        this.isReadOnly = true;
      }

      this.handleImageBaseURL();
      this.image =
        this.baseUrl + '/' + cleanUpImagePath(this.record.images[0].path);
      this.images = cleanUpImagesUrl(this.record.images);

      // set the width of image
      this.windowResize();
      this.loadExportJson();
    },

    async getInvoiceDataByDocId(docId: string) {
      try {
        this.showLoading();
        await this.getDocumentById(docId);
        if (!this.record.doc_id) {
          throw { message: 'INVALID_DOCUMENT' };
        }
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.hideLoading();
      }
    },

    getUpdatedFieldSettings(): any {
      this.layoutSettings = {};
      let groups = this.record.layout.groups;

      groups.forEach((group: any, index: any) => {
        group.rows.forEach((row: any, index: any) => {
          row.forEach((subRow: any, index: any) => {
            let field_name = subRow.field_name;
            this.layoutSettings[field_name] = subRow;
          });
        });
      });
    },
    goHelp() {
      window.open('https://docs.cloudintegration.eu/');
    },

    windowResize() {
      setTimeout(() => {
        let imageElm = $('#image_container') as HTMLElement;
        this.imageWidth = imageElm.offsetWidth;
        this.imageHeight = imageElm.offsetHeight;
        this.refreshAnnotationView++;
      }, 20);
    },

    currentPage() {
      return this.page;
    },
    prevImage() {
      let new_page_number = this.page - 1;
      let path = this.getImagePath(new_page_number);
      this.updateImage(new_page_number, path);
    },

    nextImage() {
      let new_page_number = this.page + 1;
      let path = this.getImagePath(new_page_number);
      this.updateImage(new_page_number, path);
    },

    getImagePath(page_number: number) {
      let path = '';
      for (const [key, image] of Object.entries(this.images)) {
        let imageInfo = image as dynamicObj;
        if (imageInfo.pageNumber === page_number) {
          path = imageInfo.path;
        }
      }

      return path;
    },

    updateImage(page_number: number, path: string) {
      if (!path || path === '') {
        return;
      }
      this.image = this.baseUrl + '/' + cleanUpImagePath(path);
      this.page = page_number;
    },
    handleImageBaseURL() {
      if (!this.record.images[0]) {
        return;
      }
      if (this.record.images[0].path.match(/doc2/g)) {
        this.baseUrl = DOC2API_URL;
      }
    },

    downloadFile() {
      downloadDocumentFile(this.docId, this.record.filename, this.tokenQueryParam, '.pdf');
    },
    routeToListPendingApproval() {
      this.removeDashboardFilters();
      // this.savedDashboardFilters('?filter=current-year&skip=0&limit=10&status=' + this.filter_status)
      this.$router.push('/dashboard');
    },
    async renderPendingRecordsCountView() {
      try {
        let response: any;
        let queryParams =
          '?filter=current-year&skip=0&limit=100&status=' + this.filter_status;
        let token: string = await getAuthorizationToken();

        response = await axios.get(
          addOrgIdQueryString(api.get_dashboard_data + queryParams),
          {
            headers: {
              Authorization: token,
            },
          },
        );
        if (!response.data.documents) {
          throw { message: 'no pending documents from server' };
        }

        this.pending_approval_doc_count = response.data.documents.length;
        if (this.pending_approval_doc_count < 0) {
          this.pending_approval_doc_count = 0;
        }
      } catch (err) {
        logError('something went wrong while loading document logs');
        logError(err);
      } finally {
        this.hideLoading();
      }
    },
    async renderNextPrevLinkBtns() {
      try {
        let response: any;
        let token: string = await getAuthorizationToken();

        response = await axios.get(
          addOrgIdQueryString(
            api.get_next_document +
              this.docId +
              '?doc_type=' +
              this.record.doc_type +
              '&status=' +
              this.filter_status +
              '&sort_attr=created_on',
          ),
          {
            headers: {
              Authorization: token,
            },
          },
        );
        if (response.data.success === false) {
          throw {
            message: 'cannot get response related to next or prev record',
          };
        }

        if (response.data.has_next && response.data.next_id) {
          this.next_record = response.data.next_id;
        }

        if (response.data.has_previous && response.data.previous_id) {
          this.prev_record = response.data.previous_id;
        }
      } catch (err) {
        logError('something went wrong while loading document logs');
        logError(err);
      } finally {
        this.hideLoading();
      }
    },

    routeTo(direction: string) {
      let route = 'ready-for-approval';
      if (this.second_approval) {
        route = 'ready-for-second-approval';
      }

      if (direction === 'prev' && this.prev_record) {
        this.$router.push({
          path: '/' + route + '/' + this.prev_record,
          replace: true,
        });
      }

      if (direction === 'next' && this.next_record) {
        this.$router.push('/' + route + '/' + this.next_record);
      }
    },

    updateValue(key: any, value: any) {
      if (key == 'font') {
        this.selectFont = value;
      } else if (key == 'color') {
        this.selectColor = value;
      } else if (key == 'size') {
        this.selectFontSize = value;
      }
    },

    stampAddClicked() {
      (this.$refs.child_comp as any).addTemplateAnnotation(this.selectedStamp);
    },

    async getSummeryData() {
      let response: any;
      try {
        this.showLoading();
        response = await documentDetailApiService.documentDetailApiService(
          this.docId,
        );

        if (!response.success) {
          throw response;
        }

        this.layout = response.data;

        if (response.data.invoice_data) {
          this.summeryLayout = this.layout.fields;

          if (
            this.layout.invoice_data['receipt_lines'] &&
            this.layout.invoice_data['receipt_lines'].length > 0
          ) {
            this.tablesLayout['receipt_lines'] =
              this.layout.invoice_data['receipt_lines'];
          }

          if (
            this.layout.invoice_data['line_charges'] &&
            this.layout.invoice_data['line_charges'].length > 0
          ) {
            this.tablesLayout['line_charges'] =
              this.layout.invoice_data['line_charges'];
          }
        }

        if (this.layout.debit_note_data) {
          if (
            this.layout.debit_note_data['receipt_lines'] &&
            this.layout.debit_note_data['receipt_lines'].length > 0
          ) {
            this.tablesLayout['debit_receipt_lines'] =
              this.layout.debit_note_data['receipt_lines'];
          }

          if (
            this.layout.debit_note_data['cost_lines'] &&
            this.layout.debit_note_data['cost_lines'].length > 0
          ) {
            this.tablesLayout['cost_lines'] =
              this.layout.debit_note_data['cost_lines'];
          }
        }

        if (Object.keys(this.tablesLayout).length > 0) {
          this.tableTabs = Object.keys(this.tablesLayout)[0];
        }
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.hideLoading();
      }
    },
    restoreBeforeLeave() {
      this.record = {};
      this.error = false;
      this.error_message = '';
      this.doc_status = '';
      this.page = 1;
    },
    async loadExportJson() {
      try {
        let response = await documentDetailApiService.getInforExportApiJson(
          this.docId,
        );
        if (!response || !response.success) {
          throw { message: response.message };
        }
        this.exportJson = response.data;
      } catch (err: any) {
        const error_message = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(error_message);
        logError(err);
        return;
      }
    },
  },
  setup() {
    const $q = useQuasar();
    let data: any = [];

    const doc_store = useDocumentStore();
    const { getDocumentById, getDocAnnotations, saveDocument } = doc_store;
    const { record, doc_status, error, error_message, page } =
      storeToRefs(doc_store);

    const dashboard_store = useDashboardStore();
    const { removeSavedFilters: removeDashboardFilters } = dashboard_store;

    const { tokenQueryParam, refreshTokenParam } = useImageAuth();
    const doc_attribute_store = useDocAttributesStore();
    const { fetchAttributes } = doc_attribute_store;

    return {
      getDocumentById,
      getDocAnnotations,
      fetchAttributes,
      removeDashboardFilters,
      tokenQueryParam,
      doc_status,
      page,
      error,
      error_message,
      record,
      image: '',
      images: data,
      baseUrl: DOC2API_URL,
      isReadOnly: false,
      pending_approval_doc_count: ref<any>(0),
      next_record: ref<any>(''),
      prev_record: ref<any>(''),
      selectColor: ref<any>('#000000'),
      selectFont: ref<any>('Helvetica'),
      selectFontSize: ref<any>(20),
      fontSizes: [] as any,
      selectedStamp: ref<any>(''),
      screenmode: ref<any>('annotate'),
    };
  },
});
</script>

